import{_ as c,C as r,o as t,c as n,a2 as o,b as s,w as d,a as i,E as l,a3 as h}from"./chunks/framework.Bqn-bhhR.js";const w=JSON.parse('{"title":"Keybindings & the Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"guide/keybindings.md","filePath":"guide/keybindings.md","lastUpdated":1794417539000}'),p={name:"guide/keybindings.md"};function m(b,e,u,g,y,k){const a=r("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="keybindings-the-dashboard" tabindex="-1">Keybindings &amp; the Dashboard <a class="header-anchor" href="#keybindings-the-dashboard" aria-label="Permalink to &quot;Keybindings &amp; the Dashboard&quot;">​</a></h1><p>Codemark ships a native, keyboard-driven dashboard (<code>codemark tui</code>) in the style of <code>lazygit</code>. It&#39;s a two-pane browser: a <strong>left sidebar</strong> (40%) with search, context, filters, and content; and a <strong>right main pane</strong> (60%) with an overview, steps, a code preview, and details.</p><blockquote><p>Requires a <a href="https://www.nerdfonts.com/" target="_blank" rel="noreferrer">Nerd Font</a> — the dashboard uses glyph icons throughout.</p></blockquote><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2>',4)),(t(),s(h,null,{default:d(()=>[l(a,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20Left%5B%22LeftPane%20%E2%80%94%2040%25%22%5D%0A%20%20%20%20SB%5B%22Search%22%5D%20--%3E%20CTX%5B%22Context%3A%20Repos%20%2F%20Owners%20%2F%20Auth%22%5D%0A%20%20%20%20CTX%20--%3E%20FLT%5B%22Filters%3A%20Tags%20%2F%20Branches%22%5D%0A%20%20%20%20FLT%20--%3E%20CNT%5B%22Content%3A%20Bookmarks%20%2F%20Collections%20%2F%20Tours%22%5D%0A%20%20end%0A%20%20subgraph%20Right%5B%22RightPane%20%E2%80%94%2060%25%22%5D%0A%20%20%20%20OV%5B%22Overview%20(markdown)%22%5D%20--%3E%20STP%5B%22Steps%3A%20Steps%20%2F%20Info%20%2F%20Query%22%5D%0A%20%20%20%20STP%20--%3E%20CP%5B%22Code%20preview%20%2B%20pager%22%5D%0A%20%20%20%20CP%20--%3E%20DT%5B%22Details%3A%20Details%20%2F%20Comments%22%5D%0A%20%20end%0A%20%20Left%20--%20%22%2B%20%2F%20-%20resize%2C%201-5%20focus%22%20--%3E%20Right%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>Each pane is a <code>TabbedPanel</code>; switch its tabs with <code>[</code> / <code>]</code>. The left content panel has three tabs (Bookmarks / Collections / Tours); the right has a steps panel (Steps / Info / Query) and a details panel (Details / Comments).</p><h2 id="global-keys" tabindex="-1">Global keys <a class="header-anchor" href="#global-keys" aria-label="Permalink to &quot;Global keys&quot;">​</a></h2><p>These work from anywhere (except while typing in the search bar, unless noted):</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>1</code>–<code>5</code></td><td>Jump to pane (matches the <code>[N]</code> border badge)</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>Cycle focus between panes</td></tr><tr><td><code>[</code> / <code>]</code></td><td>Previous / next tab within the focused panel</td></tr><tr><td><code>+</code> / <code>=</code></td><td>Grow the focused pane</td></tr><tr><td><code>-</code> / <code>_</code></td><td>Shrink the focused pane</td></tr><tr><td><code>q</code></td><td>Quit</td></tr><tr><td><code>Ctrl+C</code></td><td>Quit from anywhere (lazygit-style)</td></tr><tr><td><code>Esc</code></td><td>Back / cancel / clear search / clear filter</td></tr><tr><td><code>?</code></td><td>Toggle the context-aware keybindings help overlay</td></tr><tr><td><code>,</code></td><td>Toggle the settings overlay</td></tr><tr><td><code>s</code></td><td>Focus the search bar</td></tr><tr><td><code>/</code></td><td>Enter filter mode</td></tr></tbody></table><h2 id="content-action-keys" tabindex="-1">Content &amp; action keys <a class="header-anchor" href="#content-action-keys" aria-label="Permalink to &quot;Content &amp; action keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Activate / open the selected item</td></tr><tr><td><code>Space</code></td><td>Toggle selection (no focus move)</td></tr><tr><td><code>o</code></td><td>Open the selected bookmark in your configured editor</td></tr><tr><td><code>Ctrl+O</code></td><td>Copy bookmark ID (in Content) / copy markdown (in Info)</td></tr><tr><td><code>H</code></td><td>Heal — all bookmarks in the list (Content) / the current one (Main)</td></tr><tr><td><code>d</code></td><td>Delete (with a confirm dialog)</td></tr><tr><td><code>c</code></td><td>Copy the selected collection to another branch (opens the branch picker)</td></tr><tr><td><code>m</code></td><td>Move the selected collection to another branch (opens the branch picker)</td></tr><tr><td><code>S</code></td><td>Cycle sort order (Bookmarks / Collections)</td></tr><tr><td><code>p</code></td><td>Pull a remote tour / refresh</td></tr><tr><td><code>P</code></td><td>Push collections to a remote <code>codetours</code> server (when logged in)</td></tr></tbody></table><h2 id="vim-motions-delegated-to-child-panes" tabindex="-1">Vim motions (delegated to child panes) <a class="header-anchor" href="#vim-motions-delegated-to-child-panes" aria-label="Permalink to &quot;Vim motions (delegated to child panes)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Where</th><th>Action</th></tr></thead><tbody><tr><td><code>j</code> / <code>↓</code></td><td>lists, code, markdown</td><td>Move down (wraps)</td></tr><tr><td><code>k</code> / <code>↑</code></td><td>lists, code, markdown</td><td>Move up (wraps)</td></tr><tr><td><code>J</code> / <code>K</code></td><td>global</td><td>Scroll the visible preview by 5 lines</td></tr><tr><td><code>h</code> / <code>←</code></td><td>right pane</td><td>Previous step in a collection</td></tr><tr><td><code>l</code> / <code>→</code></td><td>right pane</td><td>Next step in a collection</td></tr><tr><td><code>n</code> / <code>N</code></td><td>markdown</td><td>Focus next / previous link</td></tr><tr><td><code>Enter</code></td><td>markdown</td><td>Open the focused link</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">No <code>gg</code> / <code>G</code> / <code>Ctrl-d</code> / <code>Ctrl-u</code></p><p>The motion set is intentionally small: <code>j</code>/<code>k</code>/<code>J</code>/<code>K</code> plus the step nav <code>h</code>/<code>l</code>. Capital <code>J</code>/<code>K</code> scroll the preview so they never collide with lowercase list navigation.</p></div><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>Press <code>s</code> (or <code>Enter</code> in the search bar) to search. The search bar shows a <code>[ FTS | Sem ]</code> segmented control. Toggle modes with <code>Ctrl+S</code> (semantic builds only). A Braille spinner indicates while semantic search runs; results are capped at 20.</p><ul><li><strong>FTS</strong> — substring search across notes, context, tags, and file paths.</li><li><strong>Sem</strong> — semantic search by meaning (local vector embeddings).</li></ul><p><code>Esc</code> clears the query and drops any in-flight results.</p><h2 id="copying-and-moving-collections-between-branches" tabindex="-1">Copying and moving collections between branches <a class="header-anchor" href="#copying-and-moving-collections-between-branches" aria-label="Permalink to &quot;Copying and moving collections between branches&quot;">​</a></h2><p><code>c</code> (copy) and <code>m</code> (move) on the Collections tab open a <strong>branch picker</strong>, the TUI version of <code>codemark tour copy</code> / <code>tour move</code>:</p><ul><li>Type to filter branches. Substring matches rank first, then subsequence matches (<code>qsc</code> finds <code>query-summary-cleanup</code>). <code>↑</code>/<code>↓</code> or <code>Ctrl+P</code>/<code>Ctrl+N</code> move the selection, <code>Ctrl+U</code> clears the filter, <code>Esc</code> cancels.</li><li>Common branches are pinned under <strong>Common</strong>: the default branch (<code>origin/HEAD</code>), <code>main</code>/<code>master</code>/<code>develop</code>/<code>dev</code>/<code>trunk</code>, and the current branch. With an empty filter, <code>Enter</code> picks the detected default branch (<code>origin/HEAD</code>, else <code>main</code>, else <code>master</code>). If that isn&#39;t the branch you want, type its name or move the selection first. Remote-only branches are listed by their short name.</li><li>The collection is planned against the branch&#39;s committed tip. If nothing matches (or the branch can&#39;t be read), a notification says why and nothing is written. Otherwise a confirmation dialog shows how many steps match and which ones will be left out. Their bookmarks are kept.</li><li>A copy is named <code>&lt;collection&gt;-&lt;branch&gt;</code>, with <code>-2</code>, <code>-3</code>… added if that name is taken.</li></ul><h2 id="overlays" tabindex="-1">Overlays <a class="header-anchor" href="#overlays" aria-label="Permalink to &quot;Overlays&quot;">​</a></h2><ul><li><strong><code>?</code> Help</strong> — a context-aware cheat-sheet of the keys relevant to your current focus, with priority bands (pinned actions always show).</li><li><strong><code>,</code> Settings</strong> — a modal with three tabs: <strong>Configuration</strong> (paths, db, model, theme), <strong>Theme</strong> (live-preview and persist), and <strong>About</strong>. Navigate with <code>j</code>/<code>k</code>, switch tabs with <code>[</code>/<code>]</code>, save with <code>Enter</code>, close with <code>Esc</code> or <code>,</code> (closing without saving reverts the theme).</li></ul><h2 id="mouse-support" tabindex="-1">Mouse support <a class="header-anchor" href="#mouse-support" aria-label="Permalink to &quot;Mouse support&quot;">​</a></h2><p>Click to focus and select list items; scroll to navigate panes. Confirm dialogs (<code>d</code> deletes) also respond to mouse.</p>',20))])}const v=c(p,[["render",m]]);export{w as __pageData,v as default};
